function assignProp(
  carry: Record<string | number | symbol, unknown>,
  key: string,
  newVal: unknown,
  originalObject: Record<string | number | symbol, unknown>,
): void {
  const propType = {}.propertyIsEnumerable.call(originalObject, key)
